coding.solution:
def zero_switch_coverage(table, sequences, start):
    covered = set()
    for events in sequences:
        state = start
        for event in events:
            key = (state, event)
            if key not in table:
                break
            covered.add(key)
            state = table[key]
    return round(100 * len(covered) / len(table), 1)

